'QZ_Printer_Name_Hint' => 'El nombre de la impresora tal como aparece en el equipo donde se ejecuta QZ Tray. Déjalo vacío para usar la impresora predeterminada de ese equipo. Haz clic en ⟳ para detectar impresoras.',
'QZ_Not_Running' => 'QZ Tray no se está ejecutando en este equipo. Instálalo desde qz.io y mantenlo abierto; luego permite este sitio web cuando QZ lo pida.',
'Detect_Printers' => 'Detectar impresoras',
'QZ_Download_Cert' => 'Descargar certificado (override.crt)',
'QZ_Setup_Title' => 'Cómo configurar la impresión con QZ Tray (una sola vez, en cada equipo que imprima etiquetas)',
'QZ_Step_Install' => '1. Instala QZ Tray en este equipo: descárgalo gratis desde qz.io, ábrelo y déjalo en ejecución (aparece en la bandeja del sistema en Windows o en la barra de menús en macOS).',
'QZ_Step_Connect' => '2. Conecta la impresora de etiquetas por USB y comprueba que está instalada en el sistema operativo (Windows: Configuración > Impresoras y escáneres — macOS: Ajustes del Sistema > Impresoras y escáneres).',
'QZ_Step_Detect' => '3. Haz clic en el botón ⟳ junto a "Nombre de la impresora" para detectar las impresoras de este equipo y selecciona tu impresora de etiquetas. Deja el campo vacío para usar la impresora predeterminada del equipo.',
'QZ_Step_Cert' => '4. Para imprimir sin ventana de permiso, descarga el certificado de abajo y cópialo en la carpeta de instalación de QZ Tray con el nombre override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Después cierra QZ Tray y vuelve a abrirlo.',
'QZ_Step_Test' => '5. Haz clic en "Imprimir etiqueta de prueba" abajo. Si QZ Tray pide permiso, pulsa Permitir; con el certificado instalado no volverá a pedirlo.',
'QZ_Step_Save' => '6. Haz clic en Enviar para guardar esta configuración. Las etiquetas de la página Imprimir código de barras se imprimirán directamente en esta impresora, sin el diálogo de impresión del navegador.',
'QZ_Setup_Note' => 'QZ Tray se ejecuta en el equipo desde el que navegas, por lo que funciona aunque Stocky esté alojado en un servidor remoto. Cada equipo que imprima etiquetas necesita tener QZ Tray instalado.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'Activar app instalable',
'PWA_Enabled_Help' => 'Permite que los navegadores ofrezcan instalar esta app en móviles, tabletas y ordenadores, y mantiene en caché las páginas para uso sin conexión. Al desactivarlo desaparece la invitación a instalar en todas partes y la caché se borra en la próxima visita.',
'PWA_Identity' => 'Identidad de la app',
'PWA_Launch' => 'Inicio y apariencia',
'PWA_App_Name' => 'Nombre de la app',
