'PWA_Short_Name' => 'Nombre corto',
'PWA_Short_Name_Help' => 'Se muestra bajo el icono en las pantallas de inicio, donde los nombres largos se recortan. Déjalo vacío para usar la parte del nombre de la app anterior a "|".',
'PWA_Description' => 'Descripción',
