'PWA_Reinstall_Notice' => 'Los dispositivos que ya instalaron la app conservan el nombre y el icono antiguos hasta que se desinstale y se vuelva a instalar.',

'Label_Render_Mode' => 'Renderizado de la etiqueta',
'Label_Render_Mode_Hint' => 'Cómo se dibuja la etiqueta. Fuentes de la impresora es lo más rápido y da el código de barras más nítido, pero solo imprime caracteres latinos básicos con la tipografía propia de la impresora. Imagen de vista previa reproduce exactamente tu diseño de etiqueta —la fuente que elijas, cualquier idioma— como lo hacen los programas de etiquetas especializados.',
'Render_Native' => 'Fuentes de la impresora (más rápido)',
'Render_Raster' => 'Imagen de vista previa (diseño exacto)',
'Label_Width_Mm' => 'Ancho de la etiqueta (mm)',
'Label_Height_Mm' => 'Alto de la etiqueta (mm)',
'Label_Size_Hint' => 'El tamaño físico de una pegatina del rollo. Debe coincidir exactamente con las etiquetas cargadas: un tamaño incorrecto hace que la impresora busque el hueco en el lugar equivocado, y cada etiqueta se imprime cada vez más desplazada.',
'Calibrate_Labels' => 'Calibrar etiquetas',
'Calibrate_Labels_Hint' => 'La impresora hace avanzar unas etiquetas para medir la pegatina y el hueco. Ejecútalo una vez tras cargar un rollo nuevo, o cuando la posición de impresión se desvíe.',
'Calibration_Sent' => 'Calibración iniciada: la impresora hará avanzar unas etiquetas en blanco para medirlas. Cuando se detenga, haz una impresión de prueba.',
'Label_Printer_Dpi' => 'Resolución del cabezal',
'Label_Printer_Dpi_Hint' => 'La mayoría de impresoras de etiquetas son de 203 ppp. ¿No estás seguro? Usa el botón "Buscar resolución" de abajo: imprime la respuesta.',
'Find_Resolution' => 'Buscar resolución',
'Find_Resolution_Hint' => 'Imprime dos etiquetas marcadas con 203 y 300. La correcta muestra un rectángulo completo en la pegatina con un margen pequeño y uniforme en los cuatro lados; a la incorrecta le faltan bordes o se sale a la siguiente pegatina.',
'Dpi_Test_Sent' => 'Se están imprimiendo dos etiquetas marcadas con 203 y 300. La correcta muestra un rectángulo completo con un margen pequeño y uniforme en los cuatro lados: pon ese número en "Resolución del cabezal" y guarda.',
'Label_Offset_X' => 'Desplazamiento horizontal (mm)',
'Label_Offset_X_Hint' => 'Mueve la impresión hacia los lados en la pegatina. Úsalo cuando el texto se corte en un borde lateral; p. ej. 2.5 cuando la pegatina blanca va centrada sobre un papel soporte más ancho. Ajusta en pasos de 0.5.',
'Label_Offset_Y' => 'Desplazamiento vertical (mm)',
'Label_Offset_Y_Hint' => 'Mueve la impresión a lo largo de la etiqueta. Auméntalo si la parte superior del diseño se corta o falta; redúcelo si empieza demasiado abajo.',
'Feed_To_Tear' => 'Avanzar hasta el borde de corte',
'Feed_To_Tear_Hint' => 'Hace avanzar la etiqueta hasta la barra de corte tras cada trabajo. Déjalo desactivado si las etiquetas salen desplazadas hacia abajo o partidas entre dos pegatinas: muchas impresoras no retroceden antes de la siguiente etiqueta.',
