/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Guía de pedidos',
'Ord_Guide_Intro' => 'Cómo un pedido realizado en tu tienda en línea llega a tu stock y a tus cuentas, y dónde se registra realmente el dinero.',
'Ord_Guide_Lifecycle_Title' => 'Estado del pedido',
'Ord_Guide_Lifecycle_Pending' => 'Un pedido nuevo a la espera de tu revisión. Solo un pedido pendiente puede confirmarse o cancelarse.',
'Ord_Guide_Lifecycle_Confirmed' => 'Has aceptado el pedido. Stocky crea una venta en el almacén que elegiste y descuenta el stock; esa venta es el registro del que se alimentan tus informes de stock, pagos y beneficios.',
'Ord_Guide_Lifecycle_Shipped' => 'Has enviado el pedido. Solo es logística: el stock ya se descontó al confirmar.',
'Ord_Guide_Lifecycle_Delivered' => 'El cliente recibió el pedido. Esto es lo que inicia el plazo de devolución.',
'Ord_Guide_Lifecycle_Cancelled' => 'El pedido se descartó antes de confirmarlo, así que no se creó ninguna venta ni se descontó stock.',
'Ord_Guide_PaymentStatus_Tip' => 'Se define al finalizar la compra y no se puede editar aquí. Haz clic para ver cómo registrar el pago.',
'Ord_Guide_Payment_Title' => 'Estado del pago',
'Ord_Guide_Payment_Intro' => 'Esta columna registra cómo eligió pagar el cliente al finalizar la compra. La define la tienda y no puede editarse desde esta página; el dinero en sí se controla en la venta que se crea al confirmar el pedido.',
'Ord_Guide_Payment_Paid' => 'El cliente ya pagó en línea a través de una pasarela de pago. Al confirmar el pedido, la venta se crea como Pagada y el pago queda registrado: no hay que hacer nada más.',
'Ord_Guide_Payment_Pending' => 'Contra reembolso, transferencia bancaria u otro método de pago aplazado. Al confirmar el pedido, la venta se crea como No pagada, así que registras el dinero tú mismo cuando lo cobres; consulta los pasos de abajo.',
'Ord_Guide_Payment_Failed' => 'La pasarela rechazó el pago o el cliente lo abandonó. El pedido se cancela automáticamente.',
'Ord_Guide_MarkPaid_Title' => 'Pasar un pago de pendiente a pagado',
'Ord_Guide_MarkPaid_Step1' => 'Confirma primero el pedido aquí: la confirmación es lo que crea la venta.',
'Ord_Guide_MarkPaid_Step2' => 'Abre Ventas > Todas las ventas y busca esa venta (mismo cliente, y la página de detalles muestra el pedido en línea del que proviene).',
'Ord_Guide_MarkPaid_Step3' => 'Abre el menú de acciones de la fila y elige Crear pago.',
'Ord_Guide_MarkPaid_Step4' => 'Introduce el importe, el método de pago y la fecha, y guarda. La venta pasa a Parcial o Pagada por sí sola, según el importe.',
'Ord_Guide_MarkPaid_Note' => 'El estado de pago que se muestra aquí sigue registrando la elección hecha al comprar y no cambia. La venta es el registro contable y es lo que alimenta tus informes de pagos y beneficios. Usa Mostrar pagos en la venta para revisar o editar lo que introdujiste.',
'Ord_Guide_Notes_Title' => 'Conviene saber',
'Ord_Guide_Note_Warehouse' => 'El almacén que eliges al confirmar decide de dónde se toma el stock. Los almacenes que no pueden cubrir todo el pedido aparecen marcados como Sin stock en esa lista.',
'Ord_Guide_Note_Preorder' => 'Los artículos en preventa omiten la comprobación de stock, así que un pedido que los contenga puede confirmarse aunque aún no haya existencias.',
'Ord_Guide_Note_Flagged' => 'Una etiqueta Marcado significa que el pedido activó una comprobación antifraude al finalizar la compra. Pasa el cursor sobre la etiqueta para ver el motivo y revisa el pedido antes de confirmarlo.',
'Ord_Guide_Note_Cancel' => 'Solo se puede cancelar mientras el pedido sigue pendiente. Una vez confirmado, anúlalo a través de la venta o de una devolución del cliente.',


