'VG_Opt_Step5' => 'Haga clic en "Generar variantes". Se crea una fila por combinación y su nombre se genera automáticamente, por ejemplo "Rojo / S".',
'VG_Opt_Step6' => 'Introduzca el costo y el precio en cada fila, o escriba un valor en "Aplicar a todas" y haga clic en Costo o Precio para copiarlo en todas las filas.',
'VG_Opt_Step7' => 'Los códigos se generan automáticamente. Escriba el suyo o haga clic en el icono de actualizar para generar otro.',
'VG_Opt_Step8' => 'Opcional: marque "Muestras de color" en una opción y elija un color para cada valor; la tienda lo muestra como un punto de color.',
'VG_Rows_Title' => 'Filas de variantes',
'VG_Rows_Text' => 'Cada fila tiene imagen, código, código de barras, costo, precio, precio mayorista y precio mínimo de venta. Al crear un producto también puede introducir el stock inicial por almacén para cada variante. La etiqueta "Incompleta" indica que a la fila le falta un valor para alguna opción.',
'VG_List_Title' => 'Modo de lista simple',
'VG_List_Text' => 'Escriba un nombre de variante y pulse Intro (o haga clic en Añadir) para agregar una fila; luego complete su código y precios. Este es el comportamiento clásico y sigue disponible para los productos existentes.',
'VG_Edit_Title' => 'Edición posterior',
'VG_Edit_1' => 'Añada un valor y haga clic en "Generar variantes": solo se añaden las combinaciones que faltan. Las filas existentes conservan sus códigos, precios e historial.',
'VG_Edit_2' => 'Eliminar un valor o una opción elimina las filas que lo usan. Las filas ya guardadas se borran al guardar el producto, tras una confirmación.',
'VG_Edit_3' => 'No se puede eliminar una variante que aún tiene stock. Ajuste o transfiera su stock primero.',
'VG_Edit_4' => 'Cambiar a "Lista simple" conserva las filas y sus nombres, pero descarta las definiciones de opciones.',
'VG_Store_Title' => 'En la tienda en línea',
'VG_Store_Text' => 'Los clientes eligen un valor por opción, por ejemplo Color y luego Talla. Las combinaciones que no existen se desactivan y las agotadas aparecen tachadas. La variante elegida es la que se añade al carrito.',
