'Enable_Warehouse_Letterhead_Hint' => 'Imprime el almacén emisor en las facturas, los recibos POS y la página pública de la factura: su nombre reemplaza el nombre de la empresa, y su dirección, teléfono, email, logotipo y nota al pie reemplazan los de la empresa. Cualquier campo que quede vacío en el almacén usa la configuración global de la empresa.',
'Warehouse_Letterhead_Receipt_Notice' => 'El membrete del almacén está activado: el nombre de la tienda, la dirección y el teléfono impresos en un recibo real provienen del almacén que emitió la venta, y su nota al pie se añade debajo de la nota del cliente.',
