'Set_ModT_Shopify_Desc' => 'Sincronización con la tienda Shopify y registros.',
'Set_ModT_Salla_Desc' => 'Sincronización con la tienda Salla: productos, stock y pedidos.',
'Set_ModT_PrestaShop_Desc' => 'Sincronización con la tienda PrestaShop.',
'Set_ModT_Jumia_Desc' => 'Marketplace Jumia: envío de precios y stock, importación de pedidos.',
'Set_ModT_Documents_Desc' => 'Almacenamiento y archivo centralizado de documentos.',
'Set_ModT_Subscription_Products' => 'Productos de suscripción',
'Set_ModT_Subscription_Desc' => 'Suscripciones recurrentes a productos.',
'Set_ModT_Manufacturing_Desc' => 'Listas de materiales, órdenes de producción, centros de trabajo, calidad y planificación.',
'Set_ModT_Assets_Desc' => 'Activos de la empresa, asignaciones, mantenimiento, transferencias y depreciación.',
'Set_ModT_Projects' => 'Proyectos y tareas',
'Set_ModT_Projects_Desc' => 'Proyectos, tareas, hitos, partes de horas e informes de proyectos.',
'Set_ModT_Bookings_Desc' => 'Reservas, calendario y bandejas.',
'Set_ModT_Service_Desc' => 'Trabajos de servicio, técnicos y listas de verificación.',
'Set_ModT_Fleet_Desc' => 'Vehículos, mantenimiento, registros de combustible, asignaciones e informes de flota.',
'Set_ModT_Crm_Desc' => 'Prospectos, embudo de ventas y oportunidades, actividades y seguimientos, captación de prospectos e informes de ventas.',
'Set_ModT_Rental_Desc' => 'Contratos de alquiler, reservas, facturas y pagos, mantenimiento y gastos, cronograma de disponibilidad, artículos y clientes.',
'Set_ModT_Hospital_Desc' => 'Pacientes, médicos, citas, visitas, ingresos, salas, laboratorio y facturación.',
'Set_ModT_School_Desc' => 'Estudiantes, profesores, área académica, exámenes, horarios y cuotas.',
'Set_Sidebar_Intro_Title' => 'Arrastre y suelte para reorganizar la barra lateral',
'Set_Sidebar_Intro_Desc' => 'Reordene los módulos, reordene los elementos dentro de un módulo o arrastre un elemento a otro módulo. Los módulos siempre permanecen en el nivel superior y los elementos no pueden convertirse en módulos. La disposición guardada se aplica a todos los usuarios.',
'Set_Expand_All' => 'Expandir todo',
'Set_Collapse_All' => 'Contraer todo',
'Set_Group_Tag' => 'grupo',
'Set_Sidebar_Modules_Top_Only' => 'Los módulos solo se pueden reordenar en el nivel superior.',
'Set_Sidebar_Groups_Under_Module' => 'Los grupos solo se pueden colocar directamente bajo un módulo.',
'Set_Sidebar_Items_Inside' => 'Los elementos deben permanecer dentro de un módulo o grupo.',
'Set_Sidebar_Reset_Confirm' => '¿Restaurar la estructura original de la barra lateral para todos los usuarios?',
'Set_Filter_Source' => 'Filtrar origen…',
'Set_Regenerate' => 'Regenerar',
'Set_Error' => 'Error',
'Set_Zatca_Failed_Http' => 'FALLÓ (HTTP {code})',
'Set_Zatca_Unit_Placeholder' => 'Sucursal principal',
'Set_Zatca_Category_Placeholder' => 'Comercio minorista',
'Set_Zatca_Exemption_Placeholder' => 'Exportación de bienes',
'Set_Zatca_Reported' => 'Notificada',
'Set_Zatca_Cleared' => 'Autorizada',
'Set_Translations_For' => 'Traducciones de {name}',
'Set_Showing_Translations' => 'Mostrando {shown} de {total} traducciones',
'Set_Logout_Other_Devices' => 'Cerrar sesión en otros dispositivos',
'Set_Login_At' => 'Inicio de sesión',
'Set_Queue_Driver' => 'Controlador',
'Set_Health_Critical_Summary' => 'Un servicio informó de un error: se requiere acción.',
'Set_Health_Warning_Summary' => 'Algunas comprobaciones requieren atención (trabajos fallidos o sin copia de seguridad reciente).',
'Set_Health_Ok_Summary' => 'Todos los sistemas funcionan correctamente.',
'Set_Follow_Device' => 'Seguir el dispositivo',
'Set_Returns' => 'Devoluciones',
'Set_Todays_Sales' => 'Ventas de hoy',
'Set_Sort' => 'Ordenar',
'Set_Audit_Log' => 'Registro de auditoría',
'Set_Qb_Synced_N_Clients' => '{n} clientes sincronizados',
'Set_Qb_Synced_N_Selected' => '{n} seleccionados sincronizados',
'Set_Subscription_Reminder' => 'Recordatorio de suscripción',
'Upd_Note_Code_Changes_Lost' => 'Nota 1: Si ha realizado cambios manuales en el código, esos cambios se perderán.',
'Upd_Manual_Steps_Intro' => 'Siga estos pasos para actualizar su aplicación',
'Upd_Note_Permission_Only' => 'Nota 2: solo un administrador o un usuario con el permiso "{perm}" puede actualizar el sistema',
'Upd_Manual_Step_Backup_Db' => 'Haga una copia de seguridad de su base de datos. Vaya a {backup}, haga clic en Generar copia de seguridad (la encontrará en {path}) o exporte su base de datos desde PhpMyAdmin y guárdela en su PC.',
'Upd_Manual_Step_Backup_Files' => 'Haga una copia de seguridad de sus archivos antes de actualizar.',
'Upd_Manual_Step_Download' => 'Descargue la última versión desde su cuenta de CodeCanyon y descomprímala.',
'Upd_Manual_Step_Remove' => 'Elimine los archivos anteriores, {except}:',
'Upd_Except' => 'excepto',
'Upd_File_Label' => 'archivo: {name}',
'Upd_Folder_Label' => 'carpeta: {name}',
'Upd_Manual_Step_Reupload' => 'Vuelva a subir los archivos y carpetas de la nueva actualización, {except} las mismas tres rutas anteriores.',
'Upd_Manual_Step_Visit' => 'Visite {url} para actualizar su base de datos.',
'Upd_Manual_Step_Clear_Cache' => 'Borre por completo la caché de su navegador.',
'Upd_Manual_Step_Done' => '¡Listo! Disfrute de la aplicación actualizada.',
'Upd_Note_Blank_Pages' => 'Nota: Si alguna página no carga o aparece en blanco, asegúrese de haber borrado la caché de su navegador.',
'Upd_Guide_Before_Title' => '1. Antes de actualizar',
'Upd_Guide_Before_Download' => 'Descargue el {package} de la aplicación desde su cuenta de CodeCanyon ({path}). No lo descomprima: el actualizador necesita el ZIP tal como se descargó.',
'Upd_Latest_Full_Zip' => 'último paquete ZIP completo',
'Upd_Guide_Before_Admin' => 'Asegúrese de haber iniciado sesión como administrador con el permiso {perm}. Nadie más puede ver ni ejecutar el actualizador.',
'Upd_Guide_Before_Quiet' => 'Elija un momento tranquilo: durante la actualización, la aplicación pasa a modo de mantenimiento por poco tiempo y los demás usuarios quedan bloqueados.',
'Upd_Guide_Before_No_Manual' => '{not} necesita hacer copias de seguridad manuales, descomprimir archivos, ejecutar comandos, editar archivos de configuración ni tocar la base de datos: el actualizador hace todo eso automáticamente. (Aunque una copia de seguridad manual adicional nunca está de más).',
'Upd_Not' => 'No',
'Upd_Guide_Code_Overwritten' => 'Si ha modificado manualmente el código de la aplicación, la actualización sobrescribirá sus cambios. Sus datos, archivos subidos, configuración y .env siempre se conservan.',
'Upd_Guide_Running_Title' => '2. Ejecutar la actualización',
'Upd_Guide_Run_Open' => 'Abra {path} (esta página) y permanezca en la pestaña {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: haga clic o arrastre el paquete descargado al cuadro de carga. Los archivos grandes se suben en pequeños fragmentos, por lo que también funciona en hosting compartido con límites de subida bajos. Una suma de verificación protege contra subidas dañadas o incompletas.',
'Upd_Upload_The_Zip' => 'Suba el ZIP',
'Upd_Guide_Run_Validation' => '{auto} después de la subida (puede volver a ejecutarla con el botón {button}). El sistema comprueba: integridad del ZIP, estructura y completitud del paquete, compatibilidad de versiones (se rechazan las versiones anteriores), versión y extensiones de PHP requeridas, permisos de archivos, espacio libre en disco, conexión a la base de datos, configuración y que no haya otra actualización en curso.',
'Upd_Validation_Runs_Automatically' => 'La validación se ejecuta automáticamente',
'Upd_Guide_Run_Review' => 'Revise el panel {panel}. El botón {button} solo aparece cuando se superan todas las comprobaciones críticas. Si una comprobación falla, el mensaje le indica exactamente qué corregir.',
'Upd_Guide_Run_Click' => 'Haga clic en {button} y confirme. Después, simplemente {keep} y siga la barra de progreso. El sistema realiza, en orden:',
'Upd_Keep_Page_Open' => 'mantenga esta página abierta',
'Upd_Guide_Phase_Backup' => '{label}: se crean y se {verified} un volcado completo de la base de datos, un ZIP de todos los archivos de la aplicación que la actualización puede modificar y una copia de {env}. Sus archivos subidos ({images}) y {storage} nunca se modifican en una actualización, por lo que no se archivan. Si no se puede crear una copia de seguridad, la actualización se detiene aquí y no se cambia nada.',
'Upd_Verified' => 'verifican',
'Upd_Guide_Phase_Prepare' => '{label}: la nueva versión se extrae en un área de preparación y se valida de nuevo. La aplicación en producción sigue sin tocarse.',
'Upd_Guide_Phase_Maintenance' => '{label}: se activa el modo de mantenimiento; los visitantes ven una pantalla amigable de "Volvemos enseguida".',
'Upd_Guide_Phase_Files' => '{label}: los nuevos archivos se intercambian casi al instante; los archivos antiguos se guardan aparte para la reversión. Las rutas protegidas ({env}, {storage}, {images}) nunca se reemplazan.',
'Upd_Guide_Phase_Database' => '{label}: se ejecutan las migraciones y luego se actualizan los permisos, las traducciones y las plantillas.',
'Upd_Guide_Phase_Cache' => '{label}: se borran y regeneran todas las cachés.',
'Upd_Guide_Phase_Verify' => '{label}: las comprobaciones de estado confirman que la nueva versión arranca, que la base de datos funciona, que se ejecutaron todas las migraciones y que la configuración es válida.',
'Upd_Guide_Phase_Done' => '{label}: se desactiva el modo de mantenimiento y se limpian los archivos temporales.',
'Upd_Guide_Run_Success' => 'Cuando vea {success}, haga clic en {reload} y fuerce la recarga del navegador ({keys}) para que se carguen los nuevos recursos del panel de administración.',
'Upd_Update_Successful_Short' => 'Actualización correcta',
'Upd_Guide_No_Internet' => 'No se necesita conexión a internet durante la actualización: todo proviene del ZIP subido. Perder la conexión o cerrar el navegador NO interrumpe la actualización: el servidor recuerda exactamente dónde se detuvo.',
'Upd_Guide_Wrong_Title' => '3. Si algo sale mal',
'Upd_Guide_Wrong_Rollback' => '{label}: si algo falla después de que los archivos empezaran a cambiar (error de extracción, fallo de migración, comprobación de estado fallida, disco lleno, …), el sistema restaura automáticamente los archivos anteriores y la base de datos desde la copia de seguridad verificada, desactiva el modo de mantenimiento e informa {message}. Usted queda exactamente donde empezó.',
'Upd_Automatic_Rollback' => 'Reversión automática',
'Upd_Failed_Previous_Restored' => 'La actualización falló: se restauró la versión anterior',
'Upd_Guide_Wrong_Interrupted' => '{label} (reinicio del servidor, tiempo de espera agotado, navegador cerrado, corte de energía): al volver a abrir esta página, un aviso rojo ofrece dos opciones seguras: {resume} (reanuda desde el paso exacto en que se detuvo) o {rollback} (restaura la versión anterior desde la copia de seguridad).',
'Upd_Interrupted_Update' => 'Actualización interrumpida',
'Upd_Guide_Wrong_Unreachable' => '{label}: use la {console} independiente en {path}. Funciona incluso mientras el sitio está en modo de mantenimiento o los recursos del panel de administración están dañados, y ofrece las mismas acciones Continuar / Revertir. También hay un discreto enlace "Acceso de administrador" en la parte inferior de la pantalla de mantenimiento.',
'Upd_Admin_Unreachable' => 'Panel de administración inaccesible',
'Upd_Recovery_Console' => 'consola de recuperación',
'Upd_Guide_Wrong_Locked_Out' => '{label}: mientras se ejecuta una actualización, esta página muestra un {link}. Guárdelo si necesita volver a entrar (por ejemplo, si su sesión caducó); le permite pasar la pantalla de mantenimiento para iniciar sesión de nuevo.',
'Upd_Locked_Out_Maintenance' => 'Bloqueado por el modo de mantenimiento',
'Upd_Bypass_Link' => 'enlace de acceso directo',
'Upd_Guide_Wrong_Concurrent' => '{label}: verá {message} Solo puede ejecutarse una actualización a la vez.',
'Upd_Another_Admin_Updating' => 'Otro administrador intenta actualizar al mismo tiempo',
'Upd_Guide_Backups_Title' => '4. Copias de seguridad y restauración',
'Upd_Guide_Backups_Created' => 'Cada actualización crea una copia de seguridad {before} de tocar nada: todos los archivos de la aplicación que la actualización puede reemplazar, una copia de {env} y un volcado completo de la base de datos. Los archivos subidos y {storage} nunca se modifican en una actualización y, por tanto, no forman parte de ella: mantenga sus propias copias de seguridad de ellos. Las copias de seguridad se guardan en {path} y nunca son accesibles desde la web.',
'Upd_Before' => 'antes',
'Upd_Guide_Backups_Panel' => 'El panel {panel} de la pestaña {tab} las muestra con fecha, versión y tamaño. Desde allí puede {restore} cualquier copia de seguridad completa (archivos + base de datos; antes se toma una copia de seguridad de la base de datos actual) o {delete} las antiguas.',
'Upd_Restore_Verb' => 'restaurar',
'Upd_Delete_Verb' => 'eliminar',
'Upd_Guide_Backups_Retention' => 'Use {keep} para elegir cuántas copias de seguridad se conservan; las más antiguas se eliminan automáticamente después de cada actualización exitosa. La única copia de seguridad completa restante nunca puede eliminarse: siempre conserva una forma de volver atrás.',
'Upd_Guide_Manual_Title' => '5. Actualización manual (método alternativo)',
'Upd_Guide_Manual_Text' => 'Si prefiere actualizar manualmente, o si el cargador no puede usarse en su servidor, siga las instrucciones paso a paso de la pestaña {tab} de esta página.',
'Upd_Guide_Clear_Cache_First' => 'Si las páginas se ven rotas o en blanco después de cualquier actualización, borre primero la caché de su navegador: casi siempre es la causa.',
'Upd_Restore_Backup_Confirm' => '¿Restaurar esta copia de seguridad? Los archivos actuales y la base de datos actual serán reemplazados por la copia de seguridad. Primero se realiza una copia de seguridad de la base de datos actual. (v{version} — {date})',
'Woo_Guide_Lead' => 'Cómo una tienda WooCommerce se mantiene sincronizada con el ERP. Las líneas de cron de abajo están generadas para este servidor, por lo que pueden copiarse directamente en él.',
'Woo_Guide_Ways_Note' => 'A diferencia de Shopify, WooCommerce no envía nada al ERP por sí mismo: aquí no hay receptor de webhooks, así que todo lo que {in} al ERP llega según la programación. Solo el stock que {out} puede ser inmediato.',
'Woo_In' => 'entra',
'Woo_Out' => 'sale',
'Woo_Guide_Both_Ways_Title' => 'Ambos métodos necesitan esto primero',
'Woo_Api_Keys' => 'Claves API',
'Woo_Guide_Api_Keys_Text' => '{path}, permiso {perm}. Copie la clave de consumidor y el secreto en la pestaña {settings}, junto con la URL de la tienda: la dirección de su sitio sin barra final, p. ej. {example}.',
'Woo_Credentials_Saved' => 'credenciales guardadas',
'Woo_Not_Configured_Yet' => 'aún no configurado',
'Woo_Guide_Wp_App_Password_Title' => 'Contraseña de aplicación de WordPress (opcional)',
'Woo_Guide_Wp_App_Password_Text' => 'Solo se usa para las imágenes de productos. La API de WooCommerce transfiere productos, stock, categorías, marcas, clientes y pedidos; la API de WordPress es la que busca en la Biblioteca de medios y sube una imagen que aún no está allí.',
'Woo_Guide_Wp_App_Password_Note' => 'Use un usuario de WordPress que pueda gestionar medios y cree la contraseña en {path}. Deje ambos campos en blanco y todo se seguirá sincronizando; solo se omite la asociación de imágenes.',
'Woo_Guide_Pick_Way_Title' => 'Luego elija cómo se mantiene sincronizado',
'Woo_Right_Away' => 'Inmediatamente',
'Woo_Stock_Live' => 'stock en tiempo real',
'Woo_Stock_Not_Live' => 'stock no en tiempo real',
'Woo_Guide_Realtime_Lead' => 'Una sola dirección: stock y productos que salen del ERP. Los pedidos y las ediciones de productos hechas en WooCommerce siguen llegando según la programación; consulte la otra pestaña.',
'Woo_Push_Stock_On_Change' => 'Enviar el stock en el momento en que cambia',
'Woo_Setting_People_Miss' => 'Esta es la opción que la gente pasa por alto',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Una venta del POS {not} llega a WooCommerce por sí sola. Si está desactivada, la tienda solo se entera en la siguiente sincronización de stock (una hora, por defecto) y en ese intervalo puede vender una unidad que ya vendió en caja.',
'Woo_Does_Not' => 'no',
'Woo_Guide_Tick_Instant' => 'Marque {option} en la pestaña {settings}. Esa es toda la configuración: sin worker, sin cron. Cada venta, devolución, ajuste, transferencia y compra recibida envía entonces solo esos productos, justo después de guardar la venta, y una venta de veinte líneas cuesta un envío, no veinte. La caja nunca espera por ello.',
'Woo_Currently' => 'Actualmente:',
'Woo_Instant_On_Text' => 'activado: stock enviado al cambiar',
'Woo_Instant_Off_Text' => 'desactivado: stock solo según la programación',
'Woo_Guide_Instant_Note' => 'Solo se envían los productos ya vinculados a WooCommerce: uno que nunca se ha sincronizado no tiene nada en la tienda que corregir. Los productos variables se envían a través de su producto principal, y un combo se reenvía cuando cambia cualquiera de sus componentes. Las operaciones masivas (eliminar un producto, restablecer un almacén) escriben el stock sin disparar un evento, lo cual es una razón para mantener también la sincronización de stock cada hora.',
'Woo_Push_Products_On_Save' => 'Enviar los productos en el momento en que se guardan',
'Woo_Guide_Tick_Auto_Products' => 'Marque {option} en la pestaña {settings} y un producto creado, editado o duplicado en Stocky se enviará a WooCommerce justo después de guardarse: detalles, precio, variantes e imágenes, y luego su stock. Un producto nuevo se crea en la tienda al instante en lugar de esperar la sincronización nocturna de productos.',
'Woo_On' => 'activado',
'Woo_Off' => 'desactivado',
'Woo_Guide_Bulk_Imports_Note' => 'Las importaciones masivas no se envían una por una: ejecute una sincronización de productos después de una importación. Sincronice primero las categorías y marcas, para que un producto enviado quede en la categoría correcta.',
'Woo_Nothing_Else_To_Install' => 'Nada más que instalar',
'Woo_Guide_Same_Process' => 'Sin worker de cola, sin entrada de cron. El envío se ejecuta en el mismo proceso que atendió la venta, {after} de que la respuesta haya sido devuelta, por lo que la caja nunca espera a WooCommerce. Los envíos nunca se solapan: los cambios realizados mientras uno se está ejecutando esperan a que termine y se envían justo después.',
'Woo_After' => 'después',
'Woo_Guide_Shop_Stops_Answering' => 'Si una tienda deja de responder, se abandona tras ocho segundos y los envíos se pausan durante cinco minutos para que cada venta no vuelva a esperarla; los cambios recibidos mientras tanto se envían con el primer envío después de la pausa, y la sincronización de stock cada hora se pone al día de todos modos. Cada pausa se registra en la pestaña Registros.',
'Woo_Guide_Artisan_Exception' => 'Una excepción: un cambio de stock realizado por un comando artisan no tiene una respuesta tras la cual ejecutarse, por lo que se pone en la cola {queue}. Para que esos también se envíen con prontitud, procese esa cola:',
'Woo_Cron_Line_Copied' => 'Línea de cron copiada',
'Woo_Command_Copied' => 'Comando copiado',
'Woo_Guide_Not_Woo_Queue' => 'Deliberadamente no es la cola {queue}: esa transporta los lotes de catálogo que duran horas, y un envío instantáneo encolado detrás de uno no sería instantáneo.',
'Woo_On_A_Schedule' => 'Según una programación',
'Woo_Guide_Scheduled_Lead' => 'Todo se vuelve a comprobar cada cierto tiempo, en ambas direcciones. Así es como los pedidos llegan al ERP, cómo se publica un catálogo y lo que repara cualquier cosa que la vía rápida haya pasado por alto. Cada tarea tiene su propia entrada de cron, así que ejecute solo lo que necesite.',
'Woo_Guide_Sync_Drains_Queue' => '{command} procesa su propia cola mientras se ejecuta, por lo que estas líneas no necesitan un worker aparte. En Windows, use el Programador de tareas con el programa {program} y los mismos argumentos, iniciado en {path}.',
'Woo_Or_No_Cron' => 'O sin ningún cron',
'Woo_Guide_No_Cron_Text' => 'Cada pestaña aquí sincroniza bajo demanda, y una sincronización manual procesa sus propios lotes mientras la página está abierta, así que una tienda pequeña puede funcionar sin ninguna entrada de cron. Lo que se pierde es todo lo que ocurre mientras nadie está mirando: los pedidos solo llegan cuando alguien pulsa el botón.',
'Woo_Commands_Worth_Knowing' => 'Comandos útiles',
'Woo_Worth_Knowing' => 'Conviene saber',
'Woo_Guide_Changing_Url_Clears' => 'Cambiar la URL de la tienda o las claves API borra todas las asociaciones: productos, categorías, marcas y clientes se vuelven a sincronizar con la nueva tienda.',
'Woo_Guide_Keep_Skus' => 'Mantenga los SKU coherentes entre Stocky y WooCommerce: eso es lo que evita duplicados y lo que hace segura la revinculación.',
'Woo_Guide_Stock_Total' => 'El stock publicado en Woo es el {total}, no la cifra de un solo almacén.',
'Woo_Total_Across_Warehouses' => 'total de todos los almacenes',
'Woo_Guide_Full_Reference' => 'La referencia completa (cada alcance, cómo se comporta la cola y una lista de solución de problemas) está en {file}.',
'Woo_Way_Covers' => 'Cubre',
'Woo_Way_Covers_Realtime' => 'Solo el stock que sale del ERP: una venta del POS, una devolución, un ajuste, una compra recibida',
'Woo_Way_Covers_Scheduled' => 'Todo, en ambas direcciones: entrada de pedidos y cambios de productos, salida de catálogo y stock',
'Woo_Way_Speed' => 'Velocidad',
'Woo_Way_Seconds' => 'Segundos',
'Woo_Way_Speed_Scheduled' => 'Lo que indique en la entrada de cron (stock cada hora, pedidos cada 15 min)',
'Woo_Way_Needs' => 'Requiere',
'Woo_Way_Needs_Realtime' => 'Nada, solo la opción',
'Woo_Way_Needs_Scheduled' => 'Una entrada de cron por tarea, o nada si sincroniza manualmente',
'Woo_Way_Switched_On_At' => 'Se activa en',
'Woo_Way_Cron_Entries_Below' => 'Las entradas de cron de abajo',
'Woo_Cron_Orders' => 'Pedidos cada 15 minutos: solo los modificados desde la última ejecución.',
'Woo_Cron_Products_Pull' => 'Cambios de productos desde la tienda, cada noche a las 03:00.',
'Woo_Cron_Customers' => 'Clientes, cada noche a las 03:30.',
'Woo_Cron_Stock' => 'Stock cada hora: la red de seguridad del envío instantáneo, y la única sincronización de stock sin él.',
'Woo_Cron_Products_Push' => 'Productos aún no vinculados, cada noche a las 02:00. Los productos existentes no se sobrescriben.',
'Woo_Cmd_Stock' => 'Enviar ahora el stock de todos los productos vinculados.',
'Woo_Cmd_Products_Unsynced' => 'Publicar los productos que aún no tienen ID de WooCommerce.',
'Woo_Cmd_Orders' => 'Importar los pedidos modificados desde la última ejecución.',
'Woo_Cmd_Orders_Full' => 'Volver a escanear todos los pedidos en lugar de solo los cambios recientes.',
'Woo_Cmd_Pull' => 'Todo lo entrante a la vez: productos, pedidos, clientes.',
'Woo_Guide_Page_Title' => 'Guía de WooCommerce',
'Woo_Guide_Page_Subtitle' => 'Conexión de la tienda, lo que se ejecuta por sí solo y las entradas de cron para este servidor',
'Woo_Settings_Button' => 'Configuración de WooCommerce',
'Woo_No_Shop_Connected' => 'Aún no hay ninguna tienda conectada',
'Woo_No_Shop_Connected_Desc' => 'Todo lo siguiente sigue siendo válido: introduzca la URL de la tienda y las claves API en la página de configuración de WooCommerce y luego vuelva.',
'Woo_Wp_Username' => 'Usuario de WordPress',
'Woo_Wp_App_Password' => 'Contraseña de aplicación de WordPress',
'Woo_Settings_Instant_Hint' => 'Una venta, devolución o ajuste envía el stock solo de esos productos en el instante en que se guarda, de modo que la tienda está al día en segundos en lugar de en la siguiente sincronización de stock horaria. Nada más que instalar: el envío se ejecuta después de que la venta haya sido respondida, por lo que la caja nunca espera a WooCommerce. Más información en la pestaña {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Si lo deja desactivado, una venta del POS solo llega a WooCommerce en la siguiente sincronización de stock, hasta una hora después.',
'Woo_Settings_Auto_Products_Hint' => 'Un producto creado, editado o duplicado en Stocky se envía a WooCommerce justo después de guardarse (detalles, precio, variantes, imágenes y luego su stock) en lugar de esperar una sincronización de productos. Las importaciones masivas no se envían; ejecute una sincronización de productos después de una importación.',
'Woo_Sync_Tuning' => 'Ajuste de la sincronización',
'Woo_Sync_Tuning_Intro' => 'Los valores predeterminados son adecuados para la mayoría de tiendas. Cámbielos solo si la sincronización es lenta o agota el tiempo de espera en su hosting. Cada valor está limitado a un rango seguro, y vaciar un campo restaura su valor predeterminado.',
'Woo_Setting_This_Up' => 'Configuración',
'Woo_Setting_This_Up_Text' => 'Cómo obtener las claves API, para qué sirve la contraseña de aplicación de WordPress, las entradas de cron para las sincronizaciones programadas y cómo hacer que el stock llegue a la tienda en el momento en que cambia: todo ello, con las líneas de cron de este servidor listas para copiar, está en la pestaña Guía. Una sola copia, para que no pueda desviarse de lo que el módulo realmente hace.',
