'Telegram_G_A_Title' => 'Inmediatamente: nada que instalar',
'Telegram_G_A_Body' => 'Una venta, compra, pago o gasto guardado en Stocky (en el POS o en la administración) se envía a Telegram {after} de guardarse, en la misma solicitud. Sin entrada de cron, sin worker de cola, y el cajero nunca espera a Telegram: la venta ya ha sido respondida cuando sale el mensaje.',
'Telegram_G_Right_After' => 'justo después',
'Telegram_G_B_Title' => 'La entrada de cron: para reintentos y eventos en segundo plano',
'Telegram_G_B_Body' => 'Dos tipos de mensaje esperan en la cola propia de Telegram: un envío que falló (Telegram inaccesible por un momento), que se reintenta hasta tres veces más durante los minutos siguientes; y los eventos generados fuera de la administración, como pedidos importados de WooCommerce o Shopify y comandos artisan. Esta entrada de cron los envía, y nada más:',
'Telegram_G_Cron_Note' => 'Cada minuto es lo correcto: una ejecución sin nada pendiente termina de inmediato. En cPanel esto va en {cronJobs}; use la ruta completa a PHP 8.2+ si {php} es más antiguo. En Windows, use el Programador de tareas con el programa {program}, los argumentos {args}, iniciado en {path}.',
