'Salla_Pull_Orders_From' => 'Importar pedidos de {name}',
'Salla_Pull_Orders_Desc' => 'Los nuevos pedidos de Salla normalmente llegan solos a través de webhooks y se convierten en ventas. Use esta importación para recuperar pedidos realizados antes de configurar el webhook; los pedidos ya importados se omiten.',
