'Salla_Guide_1' => 'Cree una app (privada) en {link} y elija el flujo de autorización {mode}.',
'Salla_Guide_2' => 'Copie el {clientId} y el {clientSecret} de la app en la pestaña Conexión y guarde.',
'Salla_Guide_3' => 'En la configuración de la app, establezca la URL de callback de OAuth que se muestra en la pestaña Conexión.',
'Salla_Guide_4' => 'En la página Webhooks de la app: elija la estrategia de seguridad {signature}, copie su secreto en el campo Secreto del webhook aquí, establezca la URL del webhook que se muestra en la pestaña Conexión y suscríbase al menos a {e1}, {e2}, {e3}, {e4}, {e5} y {e6}.',
'Salla_Guide_5' => 'Haga clic en {connect} y apruebe la app en su tienda. (Las apps en Easy Mode se conectan automáticamente mediante el webhook {webhook}).',
'Salla_Guide_6' => 'Importe o envíe productos y luego envíe el stock. Los nuevos pedidos llegan automáticamente y aparecen en Ventas con referencias como {ref}.',
'Salla_Identity_Sku_Title' => 'La identidad del producto es el SKU',
'Salla_Identity_Sku_Desc' => 'El código de producto de Stocky se asocia con el SKU de Salla. Mantenga los SKU coherentes en ambos lados; los productos con variantes se asocian al importar y en los pedidos, pero no se envían en esta versión.',
'Salla_Connected_To' => 'Conectado a {name}',
