'Presta_Hero_Desc' => 'Sincronice productos, stock y pedidos con su tienda PrestaShop a través de su API de webservice.',
'Presta_Webservice_Key' => 'Clave del webservice',
'Presta_Saved_Paste_New_Key' => 'Guardada: pegue una nueva clave para reemplazarla',
'Presta_From_Menu' => 'Desde {menu}',
'Presta_Webservice_Key_Help' => 'Active el webservice en PrestaShop ({menu}), cree una clave con permisos sobre products, stock_availables, orders y customers, y péguela aquí. Se almacena en modo solo escritura.',
'Presta_Shop_Language_Id' => 'ID de idioma de la tienda',
'Presta_Shop_Language_Help' => 'ID de idioma usado para los nombres de productos al enviar (1 = el primer idioma de la tienda).',
'Presta_Push_Products_Desc' => 'Crea en PrestaShop los productos simples que faltan (con su stock actual). Los productos ya vinculados y los productos con variantes se omiten: siga editando los detalles de los productos en PrestaShop, o importe para actualizar la copia local.',
'Presta_Pull_Products_Desc' => 'Importa los productos de PrestaShop, asociando los existentes por referencia (SKU) y creando el resto. Las combinaciones se importan como su producto principal.',
'Presta_Reset_Product_Confirm' => '¿Restablecer los vínculos de productos? El historial de pedidos conserva sus vínculos.',
'Presta_Push_Stock_Desc' => 'Actualiza el stock de la tienda (stock_availables) de cada producto vinculado.',
'Presta_Pull_Orders_Desc' => 'Importa los pedidos de la tienda como ventas (referencias como {ref}), los más recientes primero. Los pedidos ya importados y los cancelados se omiten, por lo que importar con regularidad es seguro. PrestaShop no tiene webhooks: ejecute esto después de periodos de mucha actividad.',
'Presta_Guide_1' => 'En el back office de PrestaShop, abra {menu} y active el webservice.',
'Presta_Guide_2' => 'Añada una nueva clave, concediendo {rw} sobre {products} y {stock}, y {view} sobre {orders} y {customers}.',
'Presta_Guide_3' => 'Pegue la URL de la tienda y la clave en la pestaña Conexión, guarde y ejecute {test}.',
'Presta_Guide_4' => 'Importe primero los productos si la tienda ya tiene un catálogo (se asocian por referencia/SKU); envíe para crear los productos simples que faltan.',
'Presta_Guide_5' => 'Envíe el stock cada vez que cambien las cantidades e importe los pedidos con regularidad: PrestaShop no tiene webhooks, por lo que los pedidos solo llegan cuando los importa.',
'Presta_Identity_Title' => 'La identidad del producto es la referencia (SKU)',
'Presta_Identity_Desc' => 'El código de producto de Stocky se asocia con la referencia de PrestaShop. Mantenga las referencias coherentes en ambos lados; las combinaciones (variantes) se asocian en los pedidos por referencia, pero no se envían en esta versión.',
'Xero_Hero_Title' => 'Sincronización contable con Xero',
'Xero_Hero_Desc' => 'Envíe sus clientes como contactos de Xero y sus ventas como facturas, con pagos cuando haya una cuenta bancaria configurada.',
