'Xero_Payment_Account_Help' => 'Un código de cuenta bancaria. Si se establece, las ventas pagadas también registran un pago en la factura; déjelo vacío para sincronizar solo facturas.',
'Xero_Auto_Sync_Sales' => 'Sincronizar automáticamente las nuevas ventas como facturas',
