'Xero_Redirect_Uri_Title' => 'URI de redirección para la app de Xero',
'Xero_Redirect_Uri_Help' => 'Cree una "Web app" en {link} y registre esta URI de redirección. Nota: los tokens de acceso de Xero se renuevan automáticamente, pero una conexión inactiva durante más de 60 días debe volver a conectarse.',
'Xero_Total_Customers' => 'Total de clientes',
'Xero_Contacts_In_Xero' => 'Contactos en Xero',
'Xero_Total_Sales' => 'Total de ventas',
'Xero_Invoices_In_Xero' => 'Facturas en Xero',
'Xero_Payments_Recorded' => 'Pagos registrados',
'Xero_Push_Customers_To' => 'Enviar clientes a {name}',
'Xero_Push_Customers_Desc' => 'Crea o actualiza un contacto de Xero para cada cliente. Un cliente cuyo nombre ya existe en Xero se vincula a ese contacto.',
'Xero_Push_Customers' => 'Enviar clientes',
'Xero_Push_Sales_Invoices' => 'Enviar ventas como facturas',
'Xero_Push_Invoices_Desc' => 'Crea una factura AUTHORISED por venta (número de factura = la Ref. de la venta), con las líneas de la venta más líneas de envío, descuento e impuesto para que el total en Xero coincida con el total de la venta. Las ventas que ya están en Xero se omiten: las facturas nunca se editan. Los contactos que faltan se crean sobre la marcha.',
'Xero_Push_Invoices' => 'Enviar facturas',
'Xero_Reset_Contact_Confirm' => '¿Restablecer los vínculos de contactos? El siguiente envío los volverá a vincular o a crear.',
'Xero_Reset_Contact_Links' => 'Restablecer vínculos de contactos',
'Xero_Guide_1' => 'Cree una {webApp} en {link} ({menu}).',
'Xero_Guide_2' => 'Registre la URI de redirección que se muestra en la pestaña Conexión.',
'Xero_Guide_3' => 'Copie el {clientId} de la app y genere un {clientSecret}; pegue ambos aquí y guarde.',
'Xero_Guide_4' => 'Haga clic en {connect}, inicie sesión y elija la organización que desea conectar.',
'Xero_Guide_5' => 'Revise los códigos de cuenta: la cuenta de ventas recibe las líneas de factura; establezca un código de cuenta bancaria si las ventas pagadas también deben registrar pagos.',
'Xero_Guide_6' => 'Envíe primero los clientes y luego las facturas. Los números de factura son las Ref. de las ventas, por lo que Xero rechaza los duplicados incluso si se restablecen los vínculos.',
'Xero_Amounts_Title' => 'Los montos se envían tal cual, con impuestos incluidos',
'Xero_Amounts_Desc' => 'Las facturas usan líneas NoTax que reflejan exactamente la venta (artículos + envío − descuento + impuesto), por lo que los totales de Xero siempre coinciden con los de Stocky. Su contador puede reasignar las líneas de impuesto y envío a las cuentas adecuadas dentro de Xero.',
'Xero_Org_Connected' => 'Organización de Xero conectada.',
'Jumia_Hero_Title' => 'Sincronización con el marketplace Jumia',
'Jumia_Hero_Desc' => 'Envíe precios y stock a sus publicaciones de Jumia Seller Center e importe los pedidos del marketplace como ventas.',
'Jumia_Api_Url_Label' => 'URL de la API (el endpoint de Seller Center de su país)',
'Jumia_Account_Email' => 'Email de la cuenta (User ID)',
'Jumia_Api_Key' => 'Clave API',
'Jumia_Prices_Stock' => 'Precios y stock',
'Jumia_Push_Prices_Stock_Title' => 'Enviar precios y stock a Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Envía el precio y la cantidad actuales de cada producto (y variante) que tenga un SKU que coincida con el {sku} de la publicación de Jumia. Las actualizaciones se envían como feeds de Seller Center y se aplican de forma asíncrona: el ID del feed se registra en la pestaña Registros, y los rechazos por artículo aparecen en la pantalla de estado de feeds de Seller Center.',
'Jumia_Push_Prices_Stock' => 'Enviar precios y stock',
'Jumia_Pull_Orders_Desc' => 'Importa los pedidos del marketplace como ventas (referencias como {ref}), asociados a sus productos por Seller SKU. Los pedidos ya importados y los cancelados se omiten, por lo que importar con regularidad es seguro. Los pagos se marcan como pagados solo para los pedidos entregados (en Jumia predomina el pago contra entrega).',
'Jumia_Guide_1' => 'En Jumia {sellerCenter}, abra {menu} y genere una clave API.',
'Jumia_Guide_2' => 'Introduzca la URL de la API de su país (p. ej. {ng} para Nigeria, {ke} para Kenia, {eg} para Egipto), el email de su cuenta de Seller Center y la clave; luego ejecute {test}.',
'Jumia_Guide_3' => 'Asegúrese de que el {sku} de cada publicación de Jumia sea igual al código de producto de Stocky: esa es la identidad usada tanto para los envíos de stock como para la asociación de pedidos.',
'Jumia_Guide_4' => 'Envíe precios y stock después de cambios en el inventario; importe los pedidos con regularidad (Jumia no tiene webhooks en esta API).',
'Jumia_Guide_5' => 'La creación de nuevas publicaciones se hace en Seller Center: Jumia exige atributos específicos por categoría y una revisión de imágenes que solo su portal gestiona bien.',
'Mailchimp_Hero_Title' => 'Sincronización de audiencia de Mailchimp',
'Mailchimp_Hero_Desc' => 'Mantenga una audiencia de Mailchimp con sus clientes, para poder realizar campañas de email sobre su base real de clientes.',
'Mailchimp_Account_Audience' => 'Cuenta y audiencia',
'Mailchimp_Api_Key_Ph' => 'p. ej. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} miembros)',
'Mailchimp_Load_Audiences_Ph' => 'Cargue las audiencias para elegir una',
'Mailchimp_Load_Audiences' => 'Cargar audiencias',
'Mailchimp_Double_Optin_Label' => 'Doble opt-in: los nuevos miembros reciben un email de confirmación antes de unirse',
'Mailchimp_Double_Optin_Hint' => '(recomendado para el RGPD)',
'Mailchimp_Auto_Sync_Customers' => 'Sincronizar automáticamente los nuevos clientes a medida que se crean',
'Mailchimp_With_Email' => 'Con email',
'Mailchimp_Push_Desc' => 'Agrega o actualiza en la audiencia seleccionada a cada cliente que tenga dirección de email (incluidos nombre y teléfono). Los miembros existentes conservan su estado de suscripción: nadie que se haya dado de baja vuelve a suscribirse. Los clientes sin email quedan fuera.',
'Mailchimp_Double_Optin_Off_Title' => 'El doble opt-in está desactivado',
'Mailchimp_Double_Optin_Off_Desc' => 'Los nuevos miembros se añadirán como suscritos sin un email de confirmación. Haga esto solo con clientes que ya aceptaron recibir marketing.',
'Mailchimp_Guide_1' => 'En Mailchimp, abra {menu} y cree una clave (termina en {suffix}: ese sufijo es su centro de datos).',
'Mailchimp_Guide_2' => 'Pegue la clave aquí, guarde, luego haga clic en {load} y elija la audiencia que desea llenar.',
'Mailchimp_Guide_3' => 'Deje el {doubleOptIn} activado salvo que sus clientes ya hayan dado su consentimiento para recibir emails de marketing.',
'Mailchimp_Double_Optin_Term' => 'doble opt-in',
'Mailchimp_Guide_4' => 'Ejecute {push} para la carga inicial; active la {autoSync} para que los nuevos clientes se unan automáticamente.',
'Mailchimp_Auto_Sync_Term' => 'sincronización automática',
'Mailchimp_Consent_Title' => 'El consentimiento importa',
'Mailchimp_Consent_Desc' => 'Enviar emails a personas que nunca aceptaron recibir marketing puede infringir el RGPD/CAN-SPAM y provocar la suspensión de su cuenta de Mailchimp. El doble opt-in traslada la confirmación a Mailchimp: la opción predeterminada segura.',
'Mailchimp_No_Audiences' => 'No se encontraron audiencias en esta cuenta.',
'GSheets_Hero_Title' => 'Exportaciones a Google Sheets',
