'GSheets_Guide_2' => 'Configure la {consent} (External). Mientras permanezca en "Testing", añada su cuenta de Google como usuario de prueba; tenga en cuenta que los tokens de actualización en modo de prueba caducan a los 7 días, así que debe {publish} la app para una conexión permanente.',
