'Shopify_Hook_Note_Register' => 'Al registrar se crean las suscripciones en Shopify y se dirigen automáticamente a esta dirección. No la añada manualmente en Shopify → Settings → Notifications → Webhooks: esos se firman con un secreto diferente y todas las entregas se rechazarían.',
