'Shopify_G_Lead_Store' => 'Lo que necesita esta tienda para mantenerse sincronizada. Todo lo que aparece aquí es específico de esta tienda: las rutas y los ID son reales, por lo que los comandos se pueden copiar directamente en el servidor.',
'Shopify_G_Lead_Generic' => 'Cómo una tienda Shopify se mantiene sincronizada con el ERP. Seleccione una tienda arriba para ver su propio estado, o léalo tal cual: la línea cron y la URL del webhook son las mismas sea cual sea la tienda que conecte.',
'Shopify_G_Ways_Note' => 'La mayoría de las tiendas usan ambos: el primero mantiene la tienda al día minuto a minuto y el segundo recoge lo que el primero no captó: un webhook que nunca llegó, una edición hecha directamente en el panel de Shopify, una noche en que el sitio estuvo caído.',
'Shopify_G_Both_Need' => 'Ambos modos necesitan esto primero',
'Shopify_G_Credentials' => 'Credenciales de Shopify',
'Shopify_G_Cred_Intro' => 'Desde enero de 2026 Shopify ya no crea apps personalizadas dentro del panel de administración, por lo que hay dos tipos de conexión:',
'Shopify_G_Cred_DevDash' => '{app} (cualquier tienda que se conecte ahora) — {path}. Conceda los permisos (scopes) de Admin API para lo que sincroniza esta tienda, instale la app en la tienda y copie el {clientId} y el {clientSecret} desde la página Settings de la app en {where}. El ERP los intercambia por sí mismo por un token de acceso y lo renueva antes de que caduque cada 24 horas. El client secret también firma los webhooks, así que no se necesita nada más. La app y la tienda deben estar en la misma organización de Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'App del Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (creada en el panel antes de 2026): sigue funcionando sin cambios con su {token} ({prefix}) y su {secret} como secreto de firma de webhooks. No es el mismo valor que el token, e intercambiarlos es el motivo habitual por el que se rechazan los webhooks.',
'Shopify_G_Legacy_App' => 'App personalizada heredada',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'almacenado',
'Shopify_G_Missing_Refused' => 'falta: las entregas se rechazarán',
'Shopify_G_Where_Data_Desc' => '{path} El almacén del ERP cuyo stock vende esta tienda y la ubicación de Shopify en la que se escribe ese stock. La sincronización de inventario y la importación de pedidos se niegan a ejecutarse sin ellos.',
'Shopify_G_Currently' => 'Actualmente: almacén {warehouse}, ubicación {location}',
'Shopify_G_Not_Set_Lower' => 'no configurado',
'Shopify_G_Ready' => 'listo',
'Shopify_G_Incomplete' => 'incompleto',
'Shopify_G_Manual_Syncs' => 'Sincronizaciones que inicia manualmente',
'Shopify_G_Manual_Desc' => 'Una sincronización iniciada desde el {centre} responde de inmediato y se ejecuta en segundo plano, en tramos cortos que continúan donde se detuvo el anterior. Un catálogo grande nunca se corta a medias por un hosting que termina las peticiones web largas (LiteSpeed, nginx, un balanceador de carga), y cerrar la página no la detiene. El proceso de trabajo para ello es una línea cron más:',
'Shopify_G_Cron_Copied' => 'Línea cron copiada',
'Shopify_G_Manual_Note' => 'Sin ella, una sincronización igualmente termina, pero solo mientras la página del Centro de sincronización permanezca abierta: cuando ningún proceso de trabajo toma una ejecución en unos segundos, la página la continúa por sí misma, una petición corta cada vez. En Windows use el Programador de tareas cada minuto: programa {program}, argumentos {args}, iniciar en {dir}.',
'Shopify_G_Then_Pick' => 'Luego elija cómo se mantiene sincronizada',
'Shopify_G_Right_Away' => 'Al instante',
'Shopify_G_Stock_Live' => 'stock en tiempo real',
'Shopify_G_Stock_Not_Live' => 'stock no en tiempo real',
'Shopify_G_Realtime_Lead' => 'Cada cambio se envía en cuanto ocurre, en segundos. Son dos mitades con interruptores separados: los {webhooks} traen los eventos propios de la tienda y el {push} envía el stock hacia fuera.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'envío instantáneo de stock',
'Shopify_G_Webhooks_In' => 'Webhooks — la tienda → el ERP',
'Shopify_G_Webhooks_Desc' => 'Pedidos, cambios de estado de pedidos y ediciones de productos, clientes y stock hechas en Shopify. Abra la tienda y pulse {button} en su {tab}; se puede pulsar dos veces sin problema. Shopify envía a:',
'Shopify_G_Webhooks_Tab' => 'pestaña Webhooks',
'Shopify_G_Webhooks_Note' => 'La dirección debe ser accesible desde Internet por HTTPS: Shopify no entrega a {localhost} ni a un dominio {test}. Cada entrega se registra una sola vez, por lo que los reintentos de Shopify no pueden crear un pedido duplicado, y una entrega fallida se puede reprocesar. Las entregas se rechazan hasta que se almacene el secreto de firma del paso 1.',
'Shopify_G_Instant_Out' => 'Envío instantáneo de stock — el ERP → la tienda',
'Shopify_G_Setting_Missed' => 'Esta es la configuración que la gente pasa por alto',
'Shopify_G_Pos_Not_Auto' => 'Una venta del POS {not} llega a Shopify por sí sola. Si se deja desactivado, la tienda solo se entera en el siguiente paso de envío de inventario, y en ese intervalo puede vender una unidad que ya vendió en la caja.',
'Shopify_G_Not' => 'no',
'Shopify_G_Tick_Push' => 'Marque {setting} en {where}. Esa es toda la configuración: sin proceso de trabajo, sin cron. Cada venta, devolución y ajuste envía entonces solo esos productos, justo después de guardar la venta, y una venta de veinte líneas cuesta un envío, no veinte. La caja nunca espera por ello.',
'Shopify_G_This_Store' => 'Esta tienda:',
'Shopify_G_Push_On' => 'activado: stock enviado al cambiar',
'Shopify_G_Push_Off' => 'desactivado: stock solo según la programación',
'Shopify_G_Push_Note' => 'Solo se envían los productos que ya tienen una asignación en Shopify, y solo los movimientos en el almacén de esta tienda. Las operaciones masivas (eliminar un producto, restablecer un almacén) escriben el stock sin disparar un evento, lo cual es una razón para mantener también el paso programado de inventario.',
'Shopify_G_Nothing_Install' => 'No hay nada más que instalar',
'Shopify_G_No_Worker_Note' => 'Ninguna de las dos mitades necesita un proceso de cola ni una entrada cron. Un webhook entrante se gestiona en la propia petición que hace Shopify; un envío de stock saliente se ejecuta en el mismo proceso que atendió la venta, {after} de que la respuesta se haya devuelto, de modo que la caja nunca espera a Shopify, y una tienda que deja de responder se abandona tras diez segundos y queda para el siguiente envío de inventario programado.',
'Shopify_G_After' => 'después',
'Shopify_G_Artisan_Note' => 'Una excepción: un cambio de stock hecho por un comando artisan no tiene una respuesta tras la cual ejecutarse, por lo que se pone en la cola {queue}. Si desea que esos también se envíen con rapidez, procese esa cola:',
'Shopify_G_On_Schedule' => 'Según una programación',
'Shopify_G_On_Lower' => 'activado',
'Shopify_G_Off_Lower' => 'desactivado',
'Shopify_G_Scheduled_Lead' => 'Todo se vuelve a comprobar periódicamente, en ambas direcciones. Es más lento que el tiempo real, pero es lo que envía el stock en las tiendas que no usan el envío instantáneo, lo que recoge un webhook perdido y la única forma de mover un catálogo completo.',
'Shopify_G_Cron_Entry' => 'La entrada cron',
'Shopify_G_Cron_Entry_Desc' => 'Nada programado se ejecuta sin ella. Una línea, solo para este módulo; añádala junto a lo que ya haya decidido programar:',
'Shopify_G_Cron_Note' => 'Cada cinco minutos es la resolución más fina que puede usar un plan, porque cinco minutos es el intervalo de paso más corto. Una entrada más espaciada simplemente se convierte en el mínimo: con {example}, un paso configurado a 5 minutos se ejecuta cada 15. En Windows use el Programador de tareas: programa {program}, argumentos {args}, iniciar en {dir}.',
'Shopify_G_Switch_On_Plan' => 'Actívelo y elija el plan',
'Shopify_G_Plan_Desc' => '{where} El interruptor decide si cron puede actuar; el plan decide qué hace. Un {step} es una entidad en una dirección con su propio intervalo: {first}, {second}. El intervalo predeterminado lo usa cualquier paso que deje vacío su propio campo.',
'Shopify_G_Step_Lower' => 'paso',
'Shopify_G_Plan_Note' => 'Deje el plan vacío y la tienda traerá pedidos y enviará stock con el intervalo predeterminado, que es lo que la mayoría de las tiendas necesita. Los pedidos solo se traen: Shopify es donde el cliente los realiza.',
'Shopify_G_Schedule_On' => 'programación activada',
'Shopify_G_Schedule_Off' => 'programación desactivada: solo manual',
'Shopify_G_When_Step_Runs' => 'Cuándo se ejecuta realmente un paso',
'Shopify_G_When_Note' => 'Un paso está pendiente cuando ese mismo paso se {started} por última vez hace más tiempo que su intervalo, según el historial de ejecuciones. Así, una sincronización iniciada manualmente pospone la siguiente automática, y un paso que sigue fallando se reintenta según su intervalo y no en cada ciclo. La Vista general de la tienda muestra la última ejecución de cada paso, la próxima hora prevista y el motivo por el que está bloqueado cuando lo está. Ejecute manualmente el primer envío del catálogo (primero con {dryRun}) antes de programarlo.',
'Shopify_G_Started_Lower' => 'inició',
'Shopify_G_Where_Setting' => 'Dónde está cada configuración',
'Shopify_G_Where_Setting_Note' => 'Todas están en una tienda existente: {path}, luego el lápiz (o {edit} en la propia página de la tienda).',
'Shopify_G_Product_Images' => 'Imágenes de productos',
'Shopify_G_Img_1' => 'Las imágenes se envían con el producto en un {push}: primero la imagen principal, luego la galería y después una por cada variante que tenga la suya propia, hasta cincuenta.',
'Shopify_G_Products_Push' => 'envío de productos',
'Shopify_G_Img_2' => 'La imagen de una variante se sube con el producto y luego se {assigned}, que es como Shopify lo modela: una variante apunta a una de las imágenes del producto. Una variante que reutiliza la imagen principal no la sube dos veces.',
'Shopify_G_Assigned' => 'asigna a esa variante',
'Shopify_G_Img_3' => 'Una imagen almacenada como archivo se {uploaded} a Shopify, no se enlaza, por lo que funciona aunque esta instalación no sea accesible desde Internet. Una imagen añadida como enlace pegado se entrega a Shopify como esa URL, que debe ser accesible públicamente.',
'Shopify_G_Uploaded' => 'sube',
'Shopify_G_Img_4' => 'Solo se vuelven a enviar cuando realmente cambian: un envío que solo modifica un precio no toca las imágenes de la tienda, porque enviarlas reemplaza el conjunto completo.',
'Shopify_G_Img_5' => 'Eliminar una imagen en el ERP {not} la elimina en Shopify. Elimínela también allí, o la tienda la seguirá mostrando.',
'Shopify_G_Commands' => 'Comandos útiles',
'Shopify_G_Command_Copied' => 'Comando copiado',
'Shopify_G_Foot' => 'Cada sincronización escribe en {logs}, y la Vista general de cada tienda muestra cuándo se ejecutó cada paso por última vez, cuándo le toca la próxima vez y qué lo está bloqueando cuando algo lo hace. Es el primer lugar donde mirar cuando una sincronización no hizo lo que esperaba.',
'Shopify_G_Covers' => 'Cubre',
'Shopify_G_Covers_Rt' => 'Pedidos y ediciones hechas en Shopify; stock que sale del ERP (una venta del POS, una devolución, un ajuste)',
'Shopify_G_Covers_Sch' => 'Todo, en ambas direcciones, incluidos los envíos de catálogo y cualquier cosa que la vía rápida no haya captado',
'Shopify_G_Speed' => 'Velocidad',
'Shopify_G_Speed_Rt' => 'Segundos',
'Shopify_G_Speed_Sch' => 'El intervalo del paso (de 5 minutos a 7 días)',
'Shopify_G_Needs' => 'Requiere',
'Shopify_G_Needs_Rt' => 'Una dirección HTTPS pública y el secreto de firma para los webhooks entrantes. El stock saliente no necesita nada',
'Shopify_G_Needs_Sch' => 'Una entrada cron que ejecute {cmd}',
'Shopify_G_Switched_On_At' => 'Se activa en',
'Shopify_G_On_Sch' => '{path}, más el plan',
'Shopify_G_Scope_Orders' => '{scope} ({extra} para pedidos de más de 60 días)',
'Shopify_G_Admin_Scopes' => 'Permisos (scopes) de Admin API',
