'Shopify_G_Tab_In_Edit' => 'Pestaña en Editar tienda',
'Shopify_G_Set_Credentials' => 'Client ID + secret o token de acceso, secreto de firma, versión de la API',
'Shopify_G_Set_Credentials_What' => 'Las credenciales de la app de Shopify (Dev Dashboard o app personalizada heredada).',
'Shopify_G_Set_Targets' => 'Almacén del ERP, ubicación de Shopify',
'Shopify_G_Set_Targets_What' => 'Qué stock vende esta tienda y dónde se registran los pedidos.',
'Shopify_G_Set_Price_What' => 'Precio minorista, mayorista o mínimo.',
'Shopify_G_Set_Create_Missing' => 'Crear productos / clientes que falten',
'Shopify_G_Set_Create_Missing_What' => 'Si una importación puede crear registros en el ERP que no logra emparejar.',
'Shopify_G_Set_Entities' => 'Qué entidades se sincronizan',
'Shopify_G_Set_Entities_What' => 'Desactivado aquí significa desactivado en todas partes: manual, programado y webhook.',
'Shopify_G_Set_Scheduler_What' => 'El interruptor del programador.',
'Shopify_G_Set_Push_What' => 'Envío instantáneo de stock, encolado al realizar una venta o ajuste.',
'Shopify_G_Set_Plan' => 'Intervalo predeterminado y plan de pasos',
'Shopify_G_Set_Plan_What' => 'Qué se ejecuta solo, en qué dirección y con qué frecuencia.',
'Shopify_G_Cmd_List' => 'Todas las tiendas: qué se ejecutaría y cuándo. No cambia nada.',
'Shopify_G_Cmd_Force' => 'El plan completo de una tienda ahora, ignorando el reloj.',
'Shopify_G_Cmd_First_Push' => 'Primer envío del catálogo: solo productos aún no vinculados.',
'Shopify_G_Cmd_Backfill' => 'Importar pedidos anteriores desde una fecha.',
'Shopify_G_Cmd_Dry' => 'Recorrerlo e informar, sin escribir nada en ningún sitio.',
