'StoreAdm_Stock_Required_Available' => '{name}: requerido {need} — disponible {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash y SSLCommerz se usan SOLO en el pago de la TIENDA EN LÍNEA.',
'StoreAdm_PG_Intro_Desc' => 'Las claves de Stripe se comparten globalmente (la administración y la tienda en línea usan la misma integración de Stripe). Cada pestaña activa o desactiva su método en el pago de la tienda en línea; Pagos fuera de línea contiene los métodos que se pagan fuera del sistema.',
'StoreAdm_PG_Used_By_Store_Only' => 'Se usa solo en el pago de la tienda en línea',
'StoreAdm_PG_Gw_Key' => 'Clave de {gw}',
'StoreAdm_PG_Gw_Secret' => 'Secreto de {gw}',
'StoreAdm_PG_Cards_Off' => 'Los pagos con tarjeta están desactivados',
'StoreAdm_PG_Cards_Off_Desc' => 'Sus claves se conservan: el pago de la tienda en línea simplemente deja de ofrecer la opción de tarjeta hasta que la vuelva a activar.',
'StoreAdm_PG_No_Stripe_Key' => 'No hay ninguna clave de Stripe almacenada',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Introduzca su clave y secreto de Stripe para empezar a aceptar pagos con tarjeta en la tienda en línea.',
'StoreAdm_PG_Gw_Client_Id' => 'Client ID de {gw}',
'StoreAdm_PG_Gw_Client_Secret' => 'Client Secret de {gw}',
'StoreAdm_PG_Sandbox' => 'Sandbox (modo de prueba)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'ACTIVADO usa {sandbox} con credenciales de sandbox; DESACTÍVELO para cobrar a cuentas reales en {live}.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => 'Webhook ID de {gw} (opcional)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'Respaldo para los pagos cuya redirección del navegador nunca llega, además de reembolsos/contracargos. Registre un webhook en {site} que apunte a la URL siguiente (eventos: {events}) y pegue aquí su Webhook ID.',
'StoreAdm_PG_Webhook_Url' => 'URL del webhook:',
'StoreAdm_PG_Gw_Disabled' => '{gw} está desactivado',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Active PayPal e introduzca el Client ID y el Secret de su app REST (desde {site}) para que los clientes puedan pagar con PayPal en el pago de la tienda en línea.',
'StoreAdm_PG_Gw_Public_Key' => 'Clave pública de {gw}',
'StoreAdm_PG_Gw_Secret_Key' => 'Clave secreta de {gw}',
'StoreAdm_PG_Paystack_Test_Live' => 'El modo de prueba o real lo determina el par de claves: las claves {test} funcionan en modo de prueba y las claves {live} cobran a tarjetas reales; no hay un interruptor de sandbox aparte.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'URL del webhook (respaldo opcional: configúrela en Settings → API Keys & Webhooks del panel de Paystack; las solicitudes se verifican con HMAC usando su clave secreta):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Active Paystack e introduzca sus claves pública y secreta (desde {site} → Settings → API Keys) para aceptar tarjetas, transferencias bancarias y dinero móvil en el pago de la tienda en línea.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (webhooks, opcional)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'El Secret Hash que configuró en Settings → Webhooks del panel de Flutterwave; los webhooks entrantes se rechazan a menos que su encabezado {header} coincida.',
'StoreAdm_PG_Flutterwave_Info' => 'Usa la API v3 de Flutterwave con claves clásicas. El modo de prueba o real lo determina el par de claves ({keys} frente a claves reales); no hay un interruptor de sandbox aparte. La moneda de la tienda debe estar habilitada en su cuenta de Flutterwave.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'URL del webhook (respaldo opcional: configúrela junto con el Secret Hash anterior en el panel de Flutterwave):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'Active Flutterwave e introduzca sus claves pública y secreta v3 (desde {site} → Settings → API) para aceptar tarjetas, dinero móvil y transferencias bancarias en el pago de la tienda en línea.',
'StoreAdm_PG_Gw_Key_Id' => 'Key ID de {gw}',
'StoreAdm_PG_Gw_Key_Secret' => 'Key Secret de {gw}',
'StoreAdm_PG_Webhook_Secret_Opt' => 'Secreto del webhook (opcional)',
'StoreAdm_PG_Razorpay_Secret_Hint' => 'El secreto que define al crear el webhook en el panel de Razorpay; los eventos entrantes se verifican con HMAC contra él y, en caso contrario, se rechazan.',
'StoreAdm_PG_Razorpay_Info' => 'Usa Razorpay Payment Links (tarjetas, UPI, banca en línea, monederos). El modo de prueba o real lo determina el par de claves ({keys}); no hay un interruptor de sandbox aparte.',
'StoreAdm_PG_Razorpay_Webhook_Url' => 'URL del webhook (respaldo opcional: regístrela con el secreto anterior en Settings → Webhooks; eventos: {events}):',
