'StoreAdm_PG_Gw_Username' => 'Usuario de {gw}',
'StoreAdm_PG_Gw_Password' => 'Contraseña de {gw}',
'StoreAdm_PG_Sandbox_Bkash_Hint' => 'ACTIVADO usa {sandbox} con sus credenciales de sandbox; DESACTÍVELO para cobrar a cuentas reales de bKash en {live}.',
'StoreAdm_PG_Bkash_Info' => 'Usa bKash Tokenized Checkout (credenciales de comerciante del portal de comerciantes de bKash). bKash cobra solo en BDT: la opción se ofrece en el pago únicamente mientras la moneda activa de la tienda sea BDT.',
'StoreAdm_PG_Bkash_Disabled_Desc' => 'Active bKash e introduzca su App Key, App Secret, usuario y contraseña de Tokenized Checkout (del portal de comerciantes de bKash) para que los clientes puedan pagar con bKash en el pago de la tienda en línea.',
'StoreAdm_PG_Gw_Store_Id' => 'Store ID de {gw}',
