'StoreAdm_PG_Sandbox_Sslcommerz_Hint' => 'ACTIVADO usa {sandbox} con credenciales de sandbox; DESACTÍVELO para cobrar a clientes reales en {live}.',
'StoreAdm_PG_Sslcommerz_Info' => 'Pago alojado que cubre tarjetas, banca móvil bKash/Nagad/Rocket y banca por Internet en Bangladés. Las credenciales provienen de su panel de comerciante de SSLCommerz (Store ID + Store Password / credenciales de API).',
