'Cr_Guide_Step_Account' => 'Añadir una cuenta de mensajería',
'Cr_Guide_Step_Account_Help' => 'Elija su empresa de mensajería y pegue las claves de API de su panel. Puede tener varias cuentas, por ejemplo una por almacén.',
'Cr_Guide_Step_Test' => 'Probar la conexión',
'Cr_Guide_Step_Test_Help' => 'Probar conexión verifica las claves y a menudo muestra los códigos que piden las opciones del transportista.',
'Cr_Guide_Step_Webhook' => 'Registre la URL del webhook',
'Cr_Guide_Step_Webhook_Help' => 'Los transportistas que envían actualizaciones necesitan la URL del webhook de la cuenta (indicada abajo) para que los estados cambien al instante. Los demás se consultan de forma programada.',
'Cr_Guide_Step_Cod' => 'Elija a dónde van los pagos contra reembolso',
'Cr_Guide_Step_Cod_Help' => 'En Configuración de transportistas, elija la cuenta en la que se registran los pagos contra reembolso y cómo se gestionan los paquetes devueltos y los cargos del transportista.',
'Cr_Guide_Step_Notify' => 'Avise a sus clientes',
'Cr_Guide_Step_Notify_Help' => 'SMS, email o WhatsApp en los estados que elija, con un enlace a la página de seguimiento.',
'Cr_Guide_Step_Book' => 'Reserve su primer pedido',
'Cr_Guide_Step_Book_Help' => 'En la lista de ventas, abra el menú de una venta y elija Enviar al transportista, o marque varias ventas y envíelas a la vez.',
'Cr_Guide_Step_Errors' => 'Vigile los errores',
'Cr_Guide_Step_Errors_Help' => 'No hay errores de transportistas en las últimas 24 horas.',
'Cr_Guide_Courier_Setup' => 'Configuración del transportista',
'Cr_Guide_Pick_Courier' => 'Elija un transportista para ver qué necesita',
'Cr_Guide_Add_This' => 'Añadir este transportista',
'Cr_Guide_You_Need' => 'Necesita',
'Cr_Guide_No_Keys' => 'Sin claves API: no hay nada que conectar.',
'Cr_Guide_Good_To_Know' => 'Conviene saber',
'Cr_Guide_Webhooks' => 'Direcciones de webhook',
'Cr_Guide_How' => 'Cómo registrarla',
'Cr_Guide_How_It_Works' => 'Cómo funciona',
'Cr_Guide_Meaning' => 'Significado',
'Cr_Guide_T_Statuses' => 'Estados',
'Cr_Guide_Statuses_Note' => 'Los estados solo avanzan, por lo que una actualización tardía nunca hace retroceder un paquete. Un paquete entregado aún puede notificarse como en devolución o devuelto.',
'Cr_Guide_S_booked' => 'El transportista tiene el pedido; nadie lo ha recogido todavía. Solo ahora se puede cancelar una reserva.',
'Cr_Guide_S_picked_up' => 'El transportista recogió el paquete.',
'Cr_Guide_S_in_transit' => 'En tránsito entre centros, en aduanas o retenido.',
'Cr_Guide_S_out_for_delivery' => 'Con el repartidor hoy.',
'Cr_Guide_S_failed_attempt' => 'Ausente, rechazado o dirección incorrecta. El transportista lo vuelve a intentar o lo devuelve.',
'Cr_Guide_S_delivered' => 'Entregado al cliente. El monto contra reembolso pasa a cobrado por el transportista.',
'Cr_Guide_S_returning' => 'De regreso hacia usted.',
'Cr_Guide_S_returned' => 'De vuelta con usted: espera en Devoluciones por revisar o se repone en stock automáticamente.',
'Cr_Guide_S_cancelled' => 'La reserva fue cancelada.',
'Cr_Guide_T_Booking' => 'Reserva de pedidos',
'Cr_Guide_B_Booking' => 'Enviar al transportista rellena el formulario a partir de la venta: destinatario, dirección, el monto aún pendiente como contra reembolso y el peso de los productos. Los transportistas con su propia lista de ciudades muestran un selector, y su elección se recuerda para esa ciudad. Los agregadores, DHL, FedEx, UPS y Lalamove ofrecen Comparar tarifas: elija un precio y Reservar lo compra. Se pueden reservar varias ventas a la vez desde la lista de ventas.',
'Cr_Guide_T_Cod' => 'Contra reembolso',
'Cr_Guide_B_Cod' => 'Un paquete contra reembolso pasa de No cobrado a Cobrado por el transportista (al entregarse) y a Pagado a usted. Los transportistas que informan los pagos realizan ellos mismos el último paso; para los demás use Actualizar contra reembolso. Con una cuenta elegida en Configuración de transportistas, el pago se registra como un pago en la venta. Los cargos del transportista pueden guardarse como gasto cuando el paquete ha finalizado.',
'Cr_Guide_T_Returns' => 'Paquetes devueltos',
'Cr_Guide_B_Returns' => 'De forma predeterminada, un paquete devuelto espera en Envíos de transportistas, en Devoluciones por revisar. Reponer crea una devolución de venta para todo el pedido y vuelve a poner los artículos en stock; Descartar no repone nada, para paquetes dañados o perdidos. En Configuración de transportistas se puede reponer automáticamente en su lugar.',
'Cr_Guide_T_Customers' => 'Mensajes a clientes y página de seguimiento',
'Cr_Guide_B_Customers' => 'Las notificaciones a clientes en Configuración de transportistas envían SMS, email o WhatsApp en los estados que marque, una vez por paquete, con su propio texto. La página de seguimiento de su tienda en línea permite a los clientes seguir un paquete por número de seguimiento, o por número de pedido y teléfono. Los clientes que devuelven paquetes con frecuencia reciben una insignia de riesgo de devolución al reservar.',
'Cr_Guide_T_Labels' => 'Etiquetas',
'Cr_Guide_B_Labels' => 'Imprimir etiqueta ofrece la etiqueta propia del transportista cuando la emite (un PDF, un enlace o una imagen); de lo contrario, una etiqueta de Stocky con el código de barras de seguimiento y el monto a cobrar. Permita las ventanas emergentes de este sitio para imprimir. DHL, FedEx y UPS entregan su etiqueta una sola vez, al reservar, y Stocky la conserva para reimpresiones.',
'Cr_Guide_T_Faq' => 'Solución de problemas',
'Cr_Guide_Q_Test' => 'Probar conexión falla',
'Cr_Guide_A_Test' => 'Las claves de prueba van con el Modo de prueba y las claves reales con Real; son distintas. Abra los registros de transportistas y lea la respuesta del transportista para conocer el motivo exacto.',
'Cr_Guide_Q_City' => 'El transportista rechaza la ciudad o la dirección',
'Cr_Guide_A_City' => 'Elija la ciudad de la lista de ciudades del transportista en el formulario de reserva; los transportistas solo aceptan sus propios nombres. Los transportistas que trabajan con direcciones postales también necesitan el estado/provincia, el código postal y el país de dos letras.',
'Cr_Guide_Q_Webhook' => 'Los estados no cambian por sí solos',
'Cr_Guide_A_Webhook' => 'Para los transportistas que envían actualizaciones, compruebe que la URL del webhook esté registrada en el transportista: los registros de transportistas muestran cada actualización recibida o por qué se rechazó (por ejemplo, un secreto incorrecto). Los demás transportistas se consultan según la programación de Configuración de transportistas, y Consultar estado ahora lo pregunta de inmediato.',
'Cr_Guide_Q_Stuck' => 'Un envío muestra un error de consulta de estado',
'Cr_Guide_A_Stuck' => 'El transportista rechazó las últimas consultas; el motivo aparece en el envío y en los registros de transportistas. Tras fallos repetidos, un envío deja de consultarse automáticamente: corrija la causa y luego use Consultar estado ahora.',
'Cr_Guide_Q_Label' => 'No se abre nada al imprimir una etiqueta',
'Cr_Guide_A_Label' => 'Su navegador bloqueó la ventana emergente. Permita las ventanas emergentes de este sitio e inténtelo de nuevo.',
'Cr_Guide_Q_Cod' => 'Un pago contra reembolso no se registró en la venta',
'Cr_Guide_A_Cod' => 'En Configuración de transportistas, el contra reembolso necesita el interruptor activado y una cuenta elegida. Sin una cuenta, los pagos solo se marcan como pagados.',
