'Tfa_Codes_Save' => 'Guarde estos códigos de recuperación en un lugar seguro. Cada uno le permite iniciar sesión una vez si pierde su teléfono. No se volverán a mostrar.',
'Tfa_Reset' => 'Restablecer dos factores',
'Tfa_Reset_Title' => '¿Restablecer la autenticación de dos factores?',
'Tfa_Reset_Help' => ':name iniciará sesión solo con su contraseña y luego podrá volver a configurar su aplicación de autenticación. Hágalo solo después de confirmar quién lo solicita.',
'Tfa_Guide_Lead' => 'La autenticación de dos factores (2FA) añade un segundo paso al inicio de sesión: después de la contraseña, el personal escribe un código de 6 dígitos de una aplicación de autenticación en su teléfono. Una contraseña robada o adivinada ya no basta para entrar.',
'Tfa_Guide_State_Required' => 'Obligatoria',
'Tfa_Guide_State_Optional' => 'No: opcional para todos',
'Tfa_Guide_State_Trust' => 'Dispositivos de confianza',
'Tfa_Guide_State_Users' => 'Usuarios con 2FA activada',
'Tfa_Guide_Staff_Title' => 'Para cada miembro del personal',
'Tfa_Guide_App_Title' => 'Instale una aplicación de autenticación',
'Tfa_Guide_App_Text' => 'Sirve cualquier aplicación compatible con códigos estándar de 6 dígitos (TOTP). Son gratuitas y funcionan sin conexión:',
'Tfa_Guide_Enable_Title' => 'Actívela desde el perfil',
'Tfa_Guide_Enable_1' => 'Abra Perfil (menú del avatar, arriba a la derecha) y busque la tarjeta "Autenticación de dos factores".',
'Tfa_Guide_Enable_2' => 'Haga clic en "Activar" y confirme con la contraseña actual.',
'Tfa_Guide_Enable_3' => 'Escanee el código QR con la aplicación o escriba la clave que aparece debajo.',
'Tfa_Guide_Enable_4' => 'Introduzca el código de 6 dígitos que muestra la aplicación para terminar.',
'Tfa_Guide_Open_Profile' => 'Abrir mi perfil',
'Tfa_Guide_Codes_Title' => 'Guarde los códigos de recuperación',
'Tfa_Guide_Codes_Text' => 'Justo después de la configuración se muestran 8 códigos de recuperación una sola vez. Cada uno sustituye una única vez a un código del teléfono, en caso de teléfono perdido, averiado o restablecido. Descárguelos o cópielos y guárdelos en un lugar seguro, lejos del teléfono.',
'Tfa_Guide_Codes_Note' => '¿Le quedan pocos? "Nuevos códigos de recuperación" en el perfil reemplaza el conjunto completo; los anteriores dejan de funcionar.',
'Tfa_Guide_Signin_Title' => 'Inicio de sesión',
'Tfa_Guide_Signin_Text' => 'Después del email y la contraseña, la página de inicio de sesión pide el código actual de la aplicación. Los códigos cambian cada 30 segundos y cada uno funciona una sola vez.',
'Tfa_Guide_Signin_Trust' => 'Marcar "No volver a preguntar en este dispositivo" omite el código en ese navegador durante :days días.',
'Tfa_Guide_Signin_Recovery' => '¿No tiene el teléfono a mano? Haga clic en "Usar un código de recuperación" y escriba uno de los códigos guardados.',
'Tfa_Guide_Admin_Title' => 'Para administradores',
'Tfa_Guide_Require_Title' => 'Hágala obligatoria',
'Tfa_Guide_Require_Text' => 'Active "Exigir autenticación de dos factores" en esta tarjeta y luego elija los roles que deben usarla, o deje la lista vacía para todos los usuarios. Haga clic en Enviar para guardar.',
'Tfa_Guide_Require_Next' => 'No se cierra la sesión de nadie. A los usuarios que aún no tienen 2FA se les guía en la configuración en la página de inicio de sesión en su próximo acceso, antes de entrar, y allí ven sus códigos de recuperación.',
'Tfa_Guide_Require_Note' => 'Los usuarios para los que es obligatoria no pueden desactivarla desde su perfil.',
'Tfa_Guide_Trust_Title' => 'Dispositivos de confianza',
'Tfa_Guide_Trust_Text' => '"Recordar dispositivos de confianza" define durante cuánto tiempo un navegador puede omitir el código tras un inicio de sesión correcto. Elija "Pedir siempre un código" para equipos compartidos o públicos, como un POS en la tienda.',
'Tfa_Guide_Trust_Note' => 'Reducir el número acorta el plazo de los dispositivos que ya son de confianza; desactivar o restablecer la 2FA los olvida todos.',
'Tfa_Guide_Lost_Title' => 'Teléfono perdido y sin códigos de recuperación',
'Tfa_Guide_Lost_Text' => 'En la página Usuarios, los usuarios con 2FA muestran "Activada" en la columna 2FA. El botón del escudo en Acciones la restablece: el usuario inicia sesión solo con la contraseña y vuelve a configurar la aplicación (o se le pide hacerlo, si es obligatoria).',
'Tfa_Guide_Lost_Warn' => 'Confirme quién lo solicita antes de restablecerla: un restablecimiento elimina la protección que la 2FA da a esa cuenta.',
'Tfa_Guide_Open_Users' => 'Abrir Usuarios',
'Tfa_Guide_Mobile_Title' => 'Aplicación móvil y API',
'Tfa_Guide_Mobile_Text' => 'La aplicación móvil y el endpoint de tokens de la API piden el mismo código. Si la 2FA es obligatoria para un usuario que aún no la ha configurado, debe iniciar sesión una vez en la web para hacerlo.',
'Tfa_Guide_Protect_Title' => 'Protección integrada',
'Tfa_Guide_Protect_1' => '5 códigos incorrectos bloquean la introducción de códigos para ese usuario durante 15 minutos, independientemente de la configuración de bloqueo anterior.',
'Tfa_Guide_Protect_2' => 'Cada código y cada código de recuperación funciona una sola vez.',
'Tfa_Guide_Protect_3' => 'Con "Registrar actividad de inicio de sesión" activado, los códigos incorrectos aparecen en la lista de actividad de inicio de sesión como "Código 2FA incorrecto".',
'Tfa_Guide_Trouble_Title' => 'Solución de problemas',
'Tfa_Guide_Faq_Clock_Q' => '“Ese código no es válido” con un código recién generado',
'Tfa_Guide_Faq_Clock_A' => 'Probablemente el reloj del teléfono esté desajustado. Los códigos dependen de la hora: configure la fecha y hora del teléfono en automático (hora de la red) y pruebe con el siguiente código.',
'Tfa_Guide_Faq_Phone_Q' => 'Cambio a un teléfono nuevo',
'Tfa_Guide_Faq_Phone_A' => 'Use la función de transferencia de la propia aplicación de autenticación, o desactive la 2FA en el perfil y vuelva a activarla con el teléfono nuevo (si es obligatoria, pida a un administrador que la restablezca).',
'Tfa_Guide_Faq_Locked_Q' => '“Demasiados códigos no válidos”',
'Tfa_Guide_Faq_Locked_A' => 'Espere el tiempo indicado (hasta 15 minutos) o pida a un administrador que restablezca la 2FA del usuario.',
'Tfa_Guide_Faq_Key_Q' => 'Nadie con 2FA puede iniciar sesión tras un cambio de servidor',
'Tfa_Guide_Faq_Key_A' => 'Los secretos de 2FA están cifrados con la APP_KEY del archivo .env. Mantenga la misma APP_KEY al mover o restaurar la aplicación; si cambió, un administrador sin 2FA debe restablecer a los usuarios afectados.',
'Tfa_Guide_Button' => 'Guía',
'Tfa_Guide_Title' => 'Guía de autenticación de dos factores',
'Sec_2fa_Pending' => ':count aún deben configurarla',
'Sec_2fa_See_Who' => 'Ver quiénes',
'Sec_2fa_Grace_Off' => 'Ninguno: configurar en el próximo inicio de sesión',
'Sec_2fa_Applied' => 'Se cerró la sesión de :count usuario(s).',
'Tfa_Guide_Rollout_Title' => 'Implántela para todos los usuarios',
'Tfa_Guide_Rollout_1' => 'Actívela primero en su propia cuenta (Perfil) para conocer los pasos.',
'Tfa_Guide_Rollout_2' => 'Indique a su equipo qué aplicación instalar y que la configuración lleva un minuto al iniciar sesión.',
'Tfa_Guide_Rollout_3' => 'Active "Exigir autenticación de dos factores", deje "Obligatoria para" vacío (= todos los usuarios) y, si lo desea, elija un periodo de gracia. Haga clic en Enviar.',
'Tfa_Guide_Rollout_4' => 'Haga clic en "Cerrar sesión de usuarios sin 2FA" para que quienes ya tienen la sesión iniciada la configuren ahora y no en algún inicio de sesión posterior. Su sesión se mantiene.',
'Tfa_Guide_Rollout_5' => 'Siga el progreso con el contador de esta tarjeta o con el filtro "Requiere configuración" de la página Usuarios.',
'Tfa_Guide_Rollout_Note' => 'Con un periodo de gracia, la pantalla de configuración muestra “Recordármelo más tarde” hasta la fecha límite; después, la configuración es obligatoria para iniciar sesión.',
'Tfa_Guide_Customers_Title' => 'Cuentas de clientes (tienda y portal de clientes)',
'Tfa_Guide_Customers_Text' => 'Los clientes también pueden proteger sus propias cuentas. Es opcional para cada cliente y nunca se impone: actívela en Configuración de la tienda → Control de acceso al registro (tienda en línea) y en Portal de clientes → Configuración del portal (portal de clientes).',
'Tfa_Guide_Customers_1' => 'Los clientes la activan desde Mi cuenta (tienda) o Perfil (portal).',
'Tfa_Guide_Customers_2' => 'Eligen un código enviado por email (lo más sencillo, sin necesidad de aplicación) o una aplicación de autenticación con códigos de recuperación.',
'Tfa_Guide_Customers_3' => 'Los códigos por email requieren una configuración de correo operativa (Configuración → Configuración de correo). Caducan a los 10 minutos.',
'Tfa_Guide_Customers_4' => 'Desactivar la opción más adelante impide nuevas configuraciones; a los clientes que ya la usan se les sigue pidiendo y pueden desactivarla ellos mismos.',
'Tfa_Required_Grace_Notice' => 'Su administrador exige la autenticación de dos factores. Puede posponerla al iniciar sesión hasta el :date; después, la configuración será obligatoria.',
